"""JFW"""
from __future__ import division
from __future__ import print_function
from builtins import str
from builtins import range
import telnetlib
import time
import re
from taf.ul.trs_e2e_fw.lib.attenuator.tool_base import ToolBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()



class Jfw(ToolBase):
    """JFW"""
    TOOL = "jfw"

    def __init__(self):
        self.session = None

    def attenuator_setup(self, device):
        """Attenuator setup"""
        ip = get_config_variable(['attenuator', device, 'ip'])
        user = get_config_variable(['attenuator', device, 'user'])
        password = get_config_variable(['attenuator', device, 'password'])
        telnet_port = get_config_variable(['attenuator', device, 'telnet_port'])
        prompt = get_config_variable(['attenuator', device, 'prompt'])
        logger.debug(prompt)
        self.source_ports = get_config_variable(['attenuator', device, 'source_ports'])
        self.target_ports = get_config_variable(['attenuator', device, 'target_ports'])
        self.session = self._login_to_attenuator(device, ip, user, password, telnet_port)

    def attenuator_configure(self, operation, **kwargs):
        """Attenuator configure"""
        if operation.lower() == 'set_attenuation':
            ports = kwargs.get('ports')
            atten_val = kwargs.get('atten_val')
            self.set_attenuation(ports, atten_val)
        elif operation.lower() == 'perform_hand_over':
            self._perform_handover(**kwargs)
        else:
            raise Exception('Operation {} not supported'.format(operation))

    def _login_to_attenuator(self, device, ip, user, password, port):
        if user == 'None' or ip == 'None' or password == 'None':
            raise Exception('Invalid Credentials. Please check the Testline config for attenuator device {}'.format(
                device))
        telnet_session = telnetlib.Telnet(str(ip), port=int(port))
        time.sleep(2)
        text_until_prompt = telnet_session.read_eager()
        logger.info('text_until_prompt', text_until_prompt)
        if 'connection open' not in text_until_prompt.lower():
            raise Exception("Telnet connection to {} failed".format(ip))
        return telnet_session

    def _perform_handover(self, **kwargs):
        atten_change_delay, atten_change_step, delay_per_direction, initial_atten, cycles, \
            max_atten = self._get_profile_params(kwargs)
        self._set_initial_attenuation_for_source_and_target_ports(initial_atten, max_atten)
        for cycle in range(cycles):
            logger.info('\n', 'Cycle: {}'.format(cycle + 1), '\n')
            self._change_attenuation_stepwise('increase', self.source_ports, initial_atten,
                                              max_atten, atten_change_step, atten_change_delay)
            time.sleep(delay_per_direction)
            self._change_attenuation_stepwise('decrease', self.source_ports, initial_atten,
                                              max_atten, atten_change_step, atten_change_delay)
            time.sleep(delay_per_direction)

    def _set_initial_attenuation_for_source_and_target_ports(self, initial_atten, max_atten):
        logger.info('Set Initial Attenuation for source and target ports', '\n')
        self.set_attenuation(self.source_ports, initial_atten)
        time.sleep(10)
        atten_for_target_ports = max_atten / 2
        self.set_attenuation(self.target_ports, atten_for_target_ports)
        time.sleep(10)

    def _get_profile_params(self, kwargs):
        profile = kwargs.get('profile')
        initial_atten = int(get_config_variable(['attenuator_profiles', profile, 'initial_atten']))  # 10
        max_atten = int(get_config_variable(['attenuator_profiles', profile, 'max_atten']))  # 60
        cycles = int(get_config_variable(['attenuator_profiles', profile, 'cycles']))  # 10
        delay_per_direction = int(get_config_variable(['attenuator_profiles', profile, 'delay_per_direction']))  # 10
        atten_change_step = int(get_config_variable(['attenuator_profiles', profile, 'atten_change_step']))  # 1
        atten_change_delay = int(get_config_variable(['attenuator_profiles', profile, 'atten_change_delay']))  # 1
        return atten_change_delay, atten_change_step, delay_per_direction, initial_atten, cycles, max_atten

    def set_attenuation(self, port_list, attenuation_val, wait_before_read=1):
        """Set Attenuation"""
        for port in port_list:
            try:
                self._send_command_and_get_output('SA{} {}\r\n'.format(port, attenuation_val), 0)
                text_until_prompt = self._send_command_and_get_output('RA{}\r\n'.format(port), wait_before_read)
                # print 'text_until_prompt', text_until_prompt
                if not re.match(r'atten#{}\s*=\s*{}\s*db'.format(port, attenuation_val),
                                text_until_prompt, re.I | re.U):
                    # if 'atten#{} = {} db'.format(port, attenuation_val) not
                    # in text_until_prompt.lower():
                    raise Exception("Failed to set attenuation value {} for port {}".format(attenuation_val, port))
                logger.info('Atten {} set for port {}'.format(attenuation_val, port))
            except EOFError:
                raise Exception("Attenuation value {} set failed for port {}".format(attenuation_val, port))

    def _send_command_and_get_output(self, command, wait_before_read):

        self.session.write(command)
        time.sleep(wait_before_read)
        return self.session.read_eager()

    def _change_attenuation_stepwise(self, direction, ports, initial_atten, max_atten, atten_change_step,
                                     atten_change_delay):
        logger.info('\n{} attenuation'.format(direction), '\n')
        wait_before_read = 1
        if direction.lower() == 'increase':
            for atten in range(initial_atten, max_atten + 1, atten_change_step):
                self.set_attenuation(ports, atten, wait_before_read)
                time.sleep(atten_change_delay - wait_before_read)
        elif direction.lower() == 'decrease':
            for atten in range(max_atten, initial_atten - 1, -atten_change_step):
                self.set_attenuation(ports, atten, wait_before_read)
                time.sleep(atten_change_delay - wait_before_read)

    def attenuator_teardown(self):
        """Attenuator teardown"""
        self.session.close()
